	var sfx_bus: int = AudioServer.get_bus_index("SFX")
	var master_bus: int = AudioServer.get_bus_index("Master")

	if not check("bus_music", music_bus != -1, "Il bus 'Music' deve esistere nel layout audio"):
		return
	if not check("bus_sfx", sfx_bus != -1, "Il bus 'SFX' deve esistere nel layout audio"):
		return

	var menu: Node = await instantiate_scene("res://options_menu.tscn")
	if not check("menu_instance", menu != null, "La scena options_menu.tscn deve istanziarsi correttamente"):
		return

	var master_slider := find_by_name(menu, "MasterSlider") as HSlider
	var music_slider := find_by_name(menu, "MusicSlider") as HSlider
	var sfx_slider := find_by_name(menu, "SFXSlider") as HSlider

	if not check("sliders_found", master_slider != null and music_slider != null and sfx_slider != null, "Tutti e tre i cursori (MasterSlider, MusicSlider, SFXSlider) devono essere presenti"):
		return

	check("slider_min", master_slider.min_value > 0.0, "La proprieta min_value dei cursori deve essere maggiore di zero (es. 0.0001) per evitare errori matematici con linear_to_db")

	# Modifica valore Master e controllo volume in decibel
	master_slider.value = 0.5
	await wait_frames(2)
	var exp_master_db: float = linear_to_db(0.5)
	var act_master_db: float = AudioServer.get_bus_volume_db(master_bus)
	check("master_volume", absf(act_master_db - exp_master_db) < 0.2, "Impostando MasterSlider a 0.5 il bus Master deve valere circa %.2f dB (trovato %.2f dB)" % [exp_master_db, act_master_db])

	# Modifica valore Music
	music_slider.value = 0.25
	await wait_frames(2)
	var exp_music_db: float = linear_to_db(0.25)
	var act_music_db: float = AudioServer.get_bus_volume_db(music_bus)
	check("music_volume", absf(act_music_db - exp_music_db) < 0.2, "Impostando MusicSlider a 0.25 il bus Music deve valere circa %.2f dB (trovato %.2f dB)" % [exp_music_db, act_music_db])

	# Modifica valore SFX
	sfx_slider.value = 0.75
	await wait_frames(2)
	var exp_sfx_db: float = linear_to_db(0.75)
	var act_sfx_db: float = AudioServer.get_bus_volume_db(sfx_bus)
