	var sfx_slider := find_by_name(menu, "SFXSlider") as HSlider
	var mute_button := find_by_name(menu, "MuteButton") as CheckButton

	if not check("mute_btn", mute_button != null, "Nel menu deve essere presente un CheckButton chiamato MuteButton"):
		return

	# Modifica i valori e attiva il muto
	master_slider.value = 0.4
	music_slider.value = 0.6
	sfx_slider.value = 0.8
	mute_button.button_pressed = true
	await wait_frames(3)

	var file_created: bool = FileAccess.file_exists("user://settings.json")
	if not check("file_exists", file_created, "Modificando i cursori o il muto deve essere creato il file user://settings.json"):
		return

	var file: FileAccess = FileAccess.open("user://settings.json", FileAccess.READ)
	var json: JSON = JSON.new()
	var parse_err: Error = json.parse(file.get_as_text())
	file.close()
	check("json_valid", parse_err == OK and json.data is Dictionary, "Il file user://settings.json deve contenere un JSON valido di tipo Dictionary")

