	check("restored_slider", absf(new_master_slider.value - 0.4) < 0.05, "Riaprendo il menu, MasterSlider deve ritrovare il valore salvato (0.4, trovato %.2f)" % new_master_slider.value)
	check("restored_mute_ui", new_mute_btn.button_pressed == true, "Riaprendo il menu, MuteButton deve risultare attivo")
	check("restored_audio_server", AudioServer.is_bus_mute(master_idx) == true, "AudioServer deve avere il bus Master silenziato in base alle impostazioni caricate")

